import{_ as t,a as n,b as r}from"./chunks/energy-price.CGaBL0Ht.js";import{_ as i,o as a,c as s,a3 as d}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Energy – Widgets","description":"Energiefluss, Verbrauch, Batteriespeicher und Preise als externes Widgetset für Home Assistant.","frontmatter":{"title":"Energy – Widgets","description":"Energiefluss, Verbrauch, Batteriespeicher und Preise als externes Widgetset für Home Assistant."},"headers":[],"relativePath":"projects/grafik-visual-studio/energy.md","filePath":"projects/grafik-visual-studio/energy.md","lastUpdated":1793126673000}'),o={name:"projects/grafik-visual-studio/energy.md"};function u(l,e,g,h,c,m){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="energy-–-widgets" tabindex="-1">Energy – Widgets <a class="header-anchor" href="#energy-–-widgets" aria-label="Permalink to &quot;Energy – Widgets&quot;">​</a></h1><p><strong>Energy 0.1.0</strong> ist ein eigenes externes Set für <strong>Grafik Visual Studio 0.1.255 oder neuer</strong>. Es gehört nicht zum Industrial-Paket. Entitätenauswahl und Livewerte funktionieren im Editor und in der Runtime; die Zeitraumwahl bedient die Runtime lokal, ohne Zustände in Home Assistant zu schreiben.</p><h2 id="originalprojekt-und-herkunft" tabindex="-1">Originalprojekt und Herkunft <a class="header-anchor" href="#originalprojekt-und-herkunft" aria-label="Permalink to &quot;Originalprojekt und Herkunft&quot;">​</a></h2><p>Vorbild ist <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-energy</a> von <strong>bluefox / GermanBluefox und Mitwirkenden</strong>, veröffentlicht unter der <strong>MIT-Lizenz</strong>. Die <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/tree/main/docs/de" target="_blank" rel="noreferrer">Originaldokumentation</a> erklärt die ioBroker-Version. Geprüfter Quellstand: <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/commit/d0a53871ea7e57c5100de2a1f2ef7b2ee82059c7" target="_blank" rel="noreferrer">d0a53871</a>, 7. Oktober 2026.</p><p>Energy ist eine <strong>eigenständige Home-Assistant-Anpassung von rockbaer2007</strong>, keine unveränderte Portierung oder offizielle ioBroker-Veröffentlichung. Renderer, Symbole und HA-Anbindung sind neu implementiert; React-/vis-2-Quellcode und Originalbilder werden nicht eingebunden. Quelle und Lizenz stehen auch in der Paket-Anleitung.</p><h2 id="bilder" tabindex="-1">Bilder <a class="header-anchor" href="#bilder" aria-label="Permalink to &quot;Bilder&quot;">​</a></h2><p>Die Bilder zeigen die Runtime mit <strong>Testdaten</strong>, keine Live-Messungen.</p><p><img src="'+t+'" alt="Energiefluss zwischen Netz, Haus, PV, Batteriespeicher und Wallbox"></p><table tabindex="0"><thead><tr><th>Batteriespeicher</th><th>Dynamischer Strompreis</th></tr></thead><tbody><tr><td><img src="'+n+'" alt="Batterie mit Ladezustand, Leistung und Restzeit"></td><td><img src="'+r+'" alt="Stündliche Strompreise mit günstigsten und teuersten Stunden"></td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Studio auf <strong>0.1.255 oder neuer</strong> aktualisieren und mit <strong>Strg+F5</strong> neu laden.</li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/master/ha_grafik_visual_studio/packages/energy/ugso.energy.wg" target="_blank" rel="noreferrer">ugso.energy.wg herunterladen</a>.</li><li>Unter <strong>Einstellungen → Widget-Pakete → Lokal</strong> installieren. Das Set erscheint als <strong>Energy</strong> in der Widgetpalette.</li><li>Widget einfügen und die Messquellen mit <strong>…</strong> aus der Home-Assistant-Entitätenauswahl übernehmen.</li></ol><p>Die Datei enthält acht deklarative Widgets, eigene SVG-Palettensymbole und Lizenz/Anleitung. Ausführbarer Paketcode ist nicht enthalten. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/energy" target="_blank" rel="noreferrer">Quellcode und Paket-Anleitung</a>.</p><h2 id="die-acht-widgets" tabindex="-1">Die acht Widgets <a class="header-anchor" href="#die-acht-widgets" aria-label="Permalink to &quot;Die acht Widgets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Funktion und Messquellen</th></tr></thead><tbody><tr><td>Energiefluss</td><td>Haus und Netz plus <strong>1–10 Zusatzknoten</strong>. Je Knoten Name, Farbe, Leistungsentität, Multiplikator, umkehrbare Flussrichtung und optional zweiter Wert mit Einheit. Flussanimation abschaltbar.</td></tr><tr><td>Energieverbrauch</td><td>Bis <strong>sechs Recorder-Reihen</strong> als Balken oder Linien, Zählerdifferenzen oder Summe einzelner Verbrauchsmengen; Stunden/Tag/Monat nach Zeitraum.</td></tr><tr><td>Verbrauchsvergleich</td><td>Aktuelle Werte von bis <strong>sechs Geräten</strong>, Balken/Linie/Kreis, Sortierung, Farbe und Einheit je Reihe. Unterschiedliche Einheiten werden nicht auf derselben Achse verrechnet.</td></tr><tr><td>Zeitauswahl</td><td>Tag, Woche, Monat oder Jahr, Datum sowie Zurück/Heute/Weiter. Ein Wähler kann mehrere Verlauf-Widgets derselben Seite steuern.</td></tr><tr><td>Autarkie und Eigenverbrauch</td><td>Zwei Ringe aus Erzeugung, Netzbezug/Einspeisung und optional Hausverbrauch. Ohne Hausquelle wird die Bilanz berechnet.</td></tr><tr><td>Batteriespeicher</td><td>Ladezustand, Leistung, Kapazität, gespeicherte Energie und rechnerische Zeit bis voll/leer. Vorzeichen für Laden wählbar, Leistung in W oder kW.</td></tr><tr><td>Energiekosten</td><td>Verbrauch × Bezugspreis + Grundgebühr pro Kalendertag − Einspeisevergütung; aktuelle Energiezähler oder Recorder-Zeitraum. Währung einstellbar.</td></tr><tr><td>Dynamischer Strompreis</td><td>JSON aus Zustand oder Attribut, Stundenbalken, aktuelle/günstige/teure Stunden und Durchschnitt. Negative Preise bleiben erhalten.</td></tr></tbody></table><h2 id="einheiten-und-unbekannte-werte" tabindex="-1">Einheiten und unbekannte Werte <a class="header-anchor" href="#einheiten-und-unbekannte-werte" aria-label="Permalink to &quot;Einheiten und unbekannte Werte&quot;">​</a></h2><p><strong>Multiplikatoren sind ausdrücklich einzustellen</strong>: z. B. <code>0.001</code> für Wh → kWh oder W → kW. Ein W-Sensor wird nicht automatisch zu einem Energiezähler. Autarkie benötigt Werte derselben Art und Einheit: entweder Leistungen oder Energie desselben Zeitraums.</p><p>Netz positiv = Bezug, negativ = Einspeisung. Eine konfigurierte separate Einspeisequelle ersetzt die negative Netzkomponente. Energiefluss: positive Knotenwerte fließen standardmäßig zum Haus, negative davon weg; für Verbraucher oder anders herum zählende Batterien <strong>Flussrichtung umkehren</strong> aktivieren.</p><p>Ohne konfigurierte oder gültige Quelle erscheint <strong>—</strong>. Unbekannte Werte werden nicht durch erfundene Vorschauwerte ersetzt. Bei Nenner 0 bleiben Quoten unbekannt. Restzeit ist eine Schätzung aus aktueller Leistung und Kapazität, keine Vorhersage der Anlage.</p><h2 id="recorder-und-zeitauswahl" tabindex="-1">Recorder und Zeitauswahl <a class="header-anchor" href="#recorder-und-zeitauswahl" aria-label="Permalink to &quot;Recorder und Zeitauswahl&quot;">​</a></h2><p>Für Verlauf und historische Kosten muss Home Assistant die numerischen Entitäten im <strong>Recorder</strong> speichern. In <strong>ID der Zeitauswahl</strong> die Widget-ID des Wählers derselben Seite eintragen, z. B. <code>widget-3</code>. Ohne Verknüpfung gelten eigener Zeitraum und Datum. Leer = aktuelles Datum.</p><p><strong>counter</strong> berechnet Zählerdifferenzen mit gehaltenen Recorder-Zuständen. Unbekannte Zustände oder ein Zähler-Reset erzeugen eine Lücke; Rücksetzungen werden nicht als Verbrauch gerechnet. <strong>sum</strong> summiert einzelne Verbrauchsmengen und ist ungeeignet für kumulative Zähler. Laufende Zeiträume enthalten nur bereits erfasste Daten; zukünftige Abschnitte bleiben unbekannt. Eine Kosten-Gesamtsumme erscheint nur bei vollständigen gültigen Daten im bereits erfassten Teil.</p><p>Grenzen: <strong>366 Tage</strong>, <strong>sechs Entitäten</strong>, <strong>20.000 Zustände je Reihe</strong>. Zu große Antworten werden mit Hinweis abgebrochen. Zeitraumgrenzen folgen der lokalen Browserzeitzone. Alte Zeiträume können wegen der Recorder-Aufbewahrung fehlen. Diese Version verwendet <strong>keine HA-Langzeitstatistiken</strong>, keine ioBroker-History und keine automatische Leistungsintegration. Grundgebühren gelten für den ausgewählten Kalenderzeitraum; im Live-Kostenmodus müssen die Zählerwerte dazu passen.</p><h2 id="preisdaten" tabindex="-1">Preisdaten <a class="header-anchor" href="#preisdaten" aria-label="Permalink to &quot;Preisdaten&quot;">​</a></h2><p>Unterstützt werden Arrays im Zustand oder einem ausgewählten Attribut, auch in <code>prices</code>, <code>today</code>, <code>data</code>, <code>values</code> oder <code>result</code> verschachtelt. Zeitfelder werden aus <code>startsAt</code>, <code>start_timestamp</code>, <code>start</code>, <code>date</code>, <code>x</code> erkannt; Preisfelder aus <code>total</code>, <code>marketprice</code>, <code>price</code>, <code>value</code>, <code>y</code>. Andere Namen lassen sich eintragen. Zeitstempel können ISO, Sekunden oder Millisekunden sein. Ein Zahlenarray entspricht den Stunden des heutigen lokalen Tages.</p><p>Preisfaktor zur Quelle einstellen: <strong>100</strong> für EUR/kWh → ct/kWh, <strong>0.1</strong> für EUR/MWh → ct/kWh. Nur ab jetzt, Stundenanzahl sowie günstige/teure Stunden und deren Farben sind einstellbar.</p><h2 id="unterschiede-zum-original" tabindex="-1">Unterschiede zum Original <a class="header-anchor" href="#unterschiede-zum-original" aria-label="Permalink to &quot;Unterschiede zum Original&quot;">​</a></h2><p>Die acht Widgetarten orientieren sich am Original; Einstellungen und Anbindung sind an Studio und Home Assistant angepasst. Diese erste Version bietet lokale Zeitraumwahl und Recorder-Zustände, keine ioBroker-OIDs oder History-Instanzen, keine vollständige Übernahme aller vis-2-Layout-/Diagrammoptionen und keine direkten Geräteschreibfunktionen.</p>',27)])])}const f=i(o,[["render",u]]);export{p as __pageData,f as default};
